if(d&&!b.fresh&&now-at<600000)return [{json:Object.assign({},d,{_cached:true})}];
if(d&&busy&&now-busy<240000)return [{json:Object.assign({},d,{_cached:true,_stale:true})}];
return [{json:Object.assign({},it,{_cached:false})}];

