/* SM8 Photos: the ServiceM8 photo attachment rows from SM8 Batch (fetched together with the other two lists). Same rows as the old HTTP node.
   Photos added with the app's 'Upload to ServiceM8' (photo library) are stored as AVIF (file_type '.avif', named 'Photo'); newer phones
   can also give HEIF. The photo filters further on (Build, Photo Inject) only know jpg/png/gif/webp/heic, so those rows are passed on
   with file_type '.jpg' (the original is kept in orig_file_type). file_type is only used by those filters; the photo itself is served
   by Photo Hook with ServiceM8's own image type, so it displays as it is. */
function kind(x){ if (!x || typeof x !== 'object' || !x.uuid) return ''; if ('activity_was_scheduled' in x || ('job_uuid' in x && 'start_date' in x)) return 'acts'; if ('related_object_uuid' in x || 'attachment_name' in x) return 'photos'; if ('first' in x && 'last' in x) return 'staff'; return ''; }
