/* Fresh Calc (GET cbs-job-file-fresh?job=N&at=T): which registers have changed since T, for this job.
   cbs_cache keys: dirty:<register>@<job> (a save that knew its job: only that job's page refreshes) and dirty:<register> (no job known,
   e.g. team or suppliers: every page refreshes). Written by Operations Backend, Document Saves, Job File and Auto Job Files (ServiceM8).
   Registers the job page does not show are ignored (IGN). Also returns the saved page's time and fingerprint (pagev:N). */
const IGN={signin:1,support:1,notices:1,leave:1,requests:1,crashes:1,checks:1,vservices:1,covertasks:1,claims:1,tbtopics:1,ramstypes:1,cphspwording:1,selectopts:1};
